INSERT INTO `v1_1199eb7bc655b4a37b7fe856fdf6f90a0d306306dfee3c7c7b2b3e4cd3de4a53` VALUES (1, "", "---", 0, "アヤネ", 1, 1, "", 1, 2);
INSERT INTO `v1_1199eb7bc655b4a37b7fe856fdf6f90a0d306306dfee3c7c7b2b3e4cd3de4a53` VALUES (3, "", "---", 6000, "アサヒ", 0, 1, "逆境に屈することなく、部員たちを引っ張る主将。ミート力を活かした安定感のある打撃が持ち味。", 2, 1);
INSERT INTO `v1_1199eb7bc655b4a37b7fe856fdf6f90a0d306306dfee3c7c7b2b3e4cd3de4a53` VALUES (0, "ホームランを連発すると、連発数に応じてパワーアップする", "アドレナリン", 16000, "部員3", 3, 1, "無愛想だが仲間を大切に想う気持ちは誰よりも強い男。ケンカで鍛えた腕っぷしが自慢のパワーヒッター。", 3, 3);
INSERT INTO `v1_1199eb7bc655b4a37b7fe856fdf6f90a0d306306dfee3c7c7b2b3e4cd3de4a53` VALUES (2, "幸運のハプニングを呼び込む", "ラッキー", 30000, "{0}", 2, 1, "みんなからの厚い信頼を集める期待の助っ人部員。実力は未知数だが幸運なハプニングを呼び込む。", 4, 2);
INSERT INTO `v1_1199eb7bc655b4a37b7fe856fdf6f90a0d306306dfee3c7c7b2b3e4cd3de4a53` VALUES (1, "", "", 50000, "選手名鑑 おまけページ", 1, 0, "みんなの知らない極秘情報がのっているおまけページ。決して誰かに見せてはいけない。", 5, 0);
